        .apply(lambda g: (g['Planned Minutes'] - g['Unplanned Downtime (min)'] - g['Changeover (min)']).sum() / g['Planned Minutes'].sum())
        .reset_index()
    )
    avail_by_line.columns = ['Line', 'availability']
