        "segment_column": "Line",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability",
        "results": avail_results
    })
except Exception:
    pass

try:
    quality_by_line = (
        df_prod.groupby('Line')
        .apply(lambda g: g['Good Count'].sum() / g['Total Count'].sum() if g['Total Count'].sum() > 0 else float('nan'))
        .reset_index()
    )
    quality_by_line.columns = ['Line', 'quality']
    quality_results = [{"name": str(row['Line']), "value": round(float(row['quality']), 6)} for _, row in quality_by_line.iterrows()]
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "quality_rate",
        "results": quality_results
