import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_prod = df[df['row_kind'].isin(['sale', 'return', 'refunded', 'other_currency', 'non_product', 'other'])] if 'row_kind' in df.columns else df.copy()
    # Use all rows except test/cancel
    valid_kinds = ['sale', 'return', 'refunded', 'non_product', 'other_currency', 'other']
    if 'row_kind' in df.columns:
        df_prod = df[df['row_kind'].isin(valid_kinds)].copy()
    else:
        df_prod = df.copy()

    # OEE by Line: sum(ideal_cycle_s * good_count / 60) / sum(planned_minutes)
    oee_by_line = []
    for line, grp in df_prod.groupby('Line'):
        total_planned = grp['Planned Minutes'].sum()
        total_ideal_good = (grp['Ideal Cycle Time (s)'] * grp['Good Count'] / 60.0).sum()
        oee_val = total_ideal_good / total_planned if total_planned > 0 else float('nan')
        oee_by_line.append({"name": str(line), "value": round(float(oee_val), 6)})

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": oee_by_line
    })

    # Overall OEE
    total_planned_all = df_prod['Planned Minutes'].sum()
    total_ideal_good_all = (df_prod['Ideal Cycle Time (s)'] * df_prod['Good Count'] / 60.0).sum()
    oee_overall = total_ideal_good_all / total_planned_all if total_planned_all > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee_overall",
        "results": [{"name": "All Lines", "value": round(float(oee_overall), 6)}]
    })

    # Also break down Good Count and Planned Minutes by Line for completeness
    for metric in ['Good Count', 'Planned Minutes']:
        seg_results = []
        for line, grp in df_prod.groupby('Line'):
            seg_results.append({"name": str(line), "value": float(grp[metric].sum())})
        result['segments'].append({
            "segment_column": "Line",
            "metric_column": metric,
            "aggregation": "sum",
            "label": None,
            "results": seg_results
        })

    result['assumptions'].append("OEE = sum(Ideal Cycle Time (s) × Good Count ÷ 60) ÷ sum(Planned Minutes), pooled per line before dividing.")
    result['assumptions'].append("Rows with row_kind not in [sale, return, refunded, non_product, other_currency, other] excluded.")
    result['assumptions'].append("1 flagged changeover row (kpi_over_max) retained as loaded; cleaning did not drop it.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

