        lambda g: g['repair_hours'].sum() / g['WONUM'].nunique()
    ).reset_index()
    wt_groups.columns = ['WORKTYPE', 'mttr']

    wt_results = [{"name": str(row['WORKTYPE']), "value": round(float(row['mttr']), 4)}
                  for _, row in wt_groups.iterrows()]
    wt_results.append({"name": "Overall", "value": round(float(overall_mttr), 4)})

