        lambda g: g['repair_hours'].sum() / g['WONUM'].nunique()
    ).reset_index()
    asset_groups.columns = ['ASSETNUM', 'mttr']
    asset_groups = asset_groups.sort_values('mttr', ascending=False).head(10)

    result['segments'].append({
        "segment_column": "ASSETNUM",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr",
