    fc_groups = fc_groups.sort_values('mttr', ascending=False).head(10)

    result['segments'].append({
        "segment_column": "FAILURECODE",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr",
        "results": [{"name": str(r['FAILURECODE']), "value": round(float(r['mttr']), 4)}
                    for _, r in fc_groups.iterrows()]
    })

    n_cm = len(df_cm)
    n_wo = distinct_wo
    result['assumptions'].append(
        f"MTTR computed on {n_wo} distinct corrective/emergency WOs ({n_cm} rows) after excluding cancelled rows and negative repair_hours."
