    shift_agg['availability'] = shift_agg['total_run'] / shift_agg['total_planned'].replace(0, float('nan'))

    avail_results = []
    for _, row in shift_agg.iterrows():
        avail_results.append({"name": str(row['Shift']), "value": round(float(row['availability']), 4)})

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability",
        "results": avail_results
    })

    run_results = []
    for _, row in shift_agg.iterrows():
        run_results.append({"name": str(row['Shift']), "value": round(float(row['total_run']), 2)})

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "sum",
        "label": "total_run_minutes",
        "results": run_results
    })

    planned_results = []
    for _, row in shift_agg.iterrows():
        planned_results.append({"name": str(row['Shift']), "value": round(float(row['total_planned']), 2)})

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "sum",
        "label": "total_planned_minutes",
        "results": planned_results
    })

    downtime_agg = df_prod.groupby('Shift')['Unplanned Downtime (min)'].sum().reset_index()
    downtime_results = [{"name": str(r['Shift']), "value": round(float(r['Unplanned Downtime (min)']), 2)}
                        for _, r in downtime_agg.iterrows()]
    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Unplanned Downtime (min)",
        "aggregation": "sum",
        "label": "total_unplanned_downtime",
        "results": downtime_results
    })

    result['assumptions'].append("Availability = sum(run) / sum(planned_minutes) per shift; run = planned - unplanned_downtime - changeover, clipped at 0.")
    result['assumptions'].append("Rows with row_kind 'test' or 'cancel' excluded from availability calculation.")
    result['assumptions'].append("1 row flagged kpi_over_max in Changeover (min) retained but clipped via run=clip(0).")

except Exception as e:
    result['segments'].append({
        "segment_column": "Shift",
