    result['assumptions'].append(f"Segmentation error: {str(e)}")

try:
    from scipy import stats as sp_stats

    shifts = df_prod['Shift'].dropna().unique().tolist()
    shift_avail_rows = {}
    for s in shifts:
        sub = df_prod[df_prod['Shift'] == s].copy()
        sub['run'] = (sub['Planned Minutes'] - sub['Unplanned Downtime (min)'] - sub['Changeover (min)']).clip(lower=0)
        valid = sub[sub['Planned Minutes'] > 0]
        if len(valid) >= 5:
